const stone = find_block({ names: ['stone', 'andesite', 'diorite', 'granite'], max_distance: 48, min_y: 50 });
if (!stone) {
  const home = depot();
  await move_to(home.x + 4, home.y, home.z + 4);
  return { done: false, detail: 'no surface stone here; walking home' };
}
const dug = await dig(stone.x, stone.y, stone.z);
if (!dug.ok) {
  return { done: false, detail: dug.detail };
}
await leave_at_depot();
return { done: true, detail: 'mined surface stone and left the bag at the depot' };
